export function recommendDataTrack(score){return score<=1?'explorer':score===2?'strategist':'architect'}
export function graphDifference(graph){return Math.abs(graph.values[graph.compare[0]]-graph.values[graph.compare[1]])}
export function dataSummary(data,kind){const sorted=[...data].sort((a,b)=>a-b);if(kind==='range')return sorted.at(-1)-sorted[0];if(kind==='median')return sorted[Math.floor(sorted.length/2)];const counts=new Map;for(const n of sorted)counts.set(n,(counts.get(n)||0)+1);return [...counts].sort((a,b)=>b[1]-a[1]||a[0]-b[0])[0][0]}
